// ============ CONFIGURACIÓN DEL CLIENTE (edita solo este bloque) ============
const CONFIG_BASE = {
  tienda: 'Tienda Demo',
  fuente: 'demo',                 // 'demo', 'csv', 'shopify' o 'woocommerce'
  csv_url: '',                    // si fuente = 'csv': enlace directo al CSV del catálogo
  moneda: 'EUR',
  dominio_tienda: '',             // solo Shopify: tu-tienda.myshopify.com (para los enlaces)
  idioma: 'es',                   // 'es' o 'en'
  tono: 'cercano',                // 'cercano', 'tecnico' o 'premium'

  motor: 'plantilla',             // 'plantilla' (sin coste, sin API) u 'openai'
  modelo: 'gpt-4o-mini',          // solo si motor = 'openai'

  max_productos: 50,              // tope por ejecución (protege la factura de la API)
  solo_sin_descripcion: true,     // true = solo productos con la descripción vacía o muy corta
  descripcion_corta: 120,         // por debajo de estos caracteres se considera "sin descripción"
  palabras_clave_extra: [],       // p. ej. ['envío 24h', 'hecho en España']

  largo_titulo: 60,               // máximo de caracteres del título SEO
  largo_meta: 155,                // máximo de caracteres de la meta descripción

  email_to: 'cliente@ejemplo.com',
  email_from: 'fichas@tu-dominio.com',   // la cuenta SMTP que envía
  telegram_chat_id: 'TU_CHAT_ID',
};
// ============================================================================

// ---- Panel único de Denoro: los ajustes del cliente llegan en la entrada ----
const __ENTRADA = $input.first().json || {};
const __limpio = (o) => Object.fromEntries(Object.entries(o || {}).filter(([, x]) => x !== '' && x !== null && x !== undefined));
const __mezclar = (b, o) => {
  const r = { ...b };
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && b[k] && typeof b[k] === 'object' && !Array.isArray(b[k])) r[k] = { ...b[k], ...__limpio(v) };
    else if (v !== undefined && v !== null) r[k] = v;
  }
  return r;
};
const CONFIG = { ...__mezclar(CONFIG_BASE, __ENTRADA.config), __token: String(__ENTRADA.token || ''), __auto: String(__ENTRADA.auto || ''), __clave: String(__ENTRADA.clave || '') };
if (!CONFIG.__token || !CONFIG.__clave) throw new Error('Esta versión se lanza desde el panel de Denoro (falta el cliente)');
if (!['demo', 'csv', 'shopify', 'woocommerce'].includes(CONFIG.fuente)) {
  throw new Error(`fuente "${CONFIG.fuente}" no válida: usa demo, csv, shopify o woocommerce`);
}
if (!['plantilla', 'openai'].includes(CONFIG.motor)) {
  throw new Error(`motor "${CONFIG.motor}" no válido: usa plantilla u openai`);
}
if (!['es', 'en'].includes(CONFIG.idioma)) throw new Error('idioma debe ser es o en');
if (!['cercano', 'tecnico', 'premium'].includes(CONFIG.tono)) {
  throw new Error('tono debe ser cercano, tecnico o premium');
}
if (CONFIG.fuente === 'csv' && !/^https?:\/\//i.test(String(CONFIG.csv_url || ''))) {
  throw new Error('Con fuente = csv hace falta un csv_url que empiece por http:// o https://');
}
if (!(CONFIG.max_productos >= 1 && CONFIG.max_productos <= 500)) {
  throw new Error('max_productos debe estar entre 1 y 500');
}
// Destinos: vacío = canal desactivado; valores de ejemplo = error claro
const PLACEHOLDER = /ejemplo\.com|tu-dominio|TU_CHAT_ID/i;
for (const k of ['email_to', 'email_from', 'telegram_chat_id']) {
  if (PLACEHOLDER.test(String(CONFIG[k] || ''))) {
    throw new Error(`Configura "${k}" en el nodo Configuración (ahora tiene un valor de ejemplo). Déjalo vacío ('') para desactivar ese canal.`);
  }
}
if (CONFIG.telegram_chat_id && !/^-?\d+$|^@\w+$/.test(String(CONFIG.telegram_chat_id))) {
  throw new Error('telegram_chat_id debe ser un número (p. ej. 123456789) o @canal');
}
if (!CONFIG.email_to && !CONFIG.telegram_chat_id) throw new Error('Configura al menos un canal: email_to o telegram_chat_id');
if (CONFIG.email_to && !CONFIG.email_from) throw new Error('Falta email_from (la cuenta SMTP que envía)');

return [{ json: {
  ...CONFIG,
  enviar_email: Boolean(CONFIG.email_to),
  enviar_telegram: Boolean(CONFIG.telegram_chat_id),
  generado_en: new Date().toISOString(),
} }];

// Convierte el CSV descargado en productos. Acepta ; o , como separador y comillas dobles.
const cfg = $('Configuración').first().json;
const entrada = $input.first();
let texto = entrada.json.data ?? entrada.json.body ?? entrada.json.texto ?? '';
if (!texto && entrada.binary) {
  const key = Object.keys(entrada.binary)[0];
  texto = Buffer.from(entrada.binary[key].data, 'base64').toString('utf8');
}
texto = String(texto).replace(/^﻿/, '').trim();
if (!texto) throw new Error('El CSV llegó vacío: revisa csv_url en el nodo Configuración');

// --- lector de CSV con comillas ---
const filas = [];
let campo = '';
let fila = [];
let comillas = false;
const sep = (texto.split('\n')[0].match(/;/g) || []).length > (texto.split('\n')[0].match(/,/g) || []).length ? ';' : ',';
for (let i = 0; i < texto.length; i++) {
  const c = texto[i];
  if (comillas) {
    if (c === '"' && texto[i + 1] === '"') { campo += '"'; i++; }
    else if (c === '"') comillas = false;
    else campo += c;
  } else if (c === '"') comillas = true;
  else if (c === sep) { fila.push(campo); campo = ''; }
  else if (c === '\n') { fila.push(campo); filas.push(fila); fila = []; campo = ''; }
  else if (c !== '\r') campo += c;
}
if (campo !== '' || fila.length) { fila.push(campo); filas.push(fila); }
if (filas.length < 2) throw new Error('El CSV no tiene filas de datos (solo cabecera o nada)');

const norm = (s) => String(s).trim().toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const cabecera = filas[0].map(norm);
const ALIAS = {
  sku: ['sku', 'referencia', 'ref', 'codigo', 'id'],
  titulo: ['titulo', 'title', 'nombre', 'name', 'producto'],
  marca: ['marca', 'brand', 'fabricante'],
  categoria: ['categoria', 'category', 'tipo', 'familia'],
  precio: ['precio', 'price', 'pvp'],
  stock: ['stock', 'existencias', 'inventario', 'cantidad', 'qty'],
  descripcion: ['descripcion', 'description', 'descripcion_larga', 'body_html'],
  url: ['url', 'enlace', 'link', 'permalink'],
};
const idx = {};
for (const [campoDestino, nombres] of Object.entries(ALIAS)) {
  const i = cabecera.findIndex((h) => nombres.includes(h));
  if (i >= 0) idx[campoDestino] = i;
}
if (idx.sku === undefined) throw new Error(`El CSV necesita una columna de referencia (sku, referencia o codigo). Encontradas: ${cabecera.join(', ')}`);
if (idx.titulo === undefined) throw new Error(`El CSV necesita una columna de título (titulo, nombre o name). Encontradas: ${cabecera.join(', ')}`);
const usadas = new Set(Object.values(idx));

const numero = (v) => {
  const n = parseFloat(String(v).replace(/[^0-9,.\-]/g, '').replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const productos = [];
const vistos = new Set();
for (const f of filas.slice(1)) {
  if (!f.some((v) => String(v).trim() !== '')) continue;
  const sku = String(f[idx.sku] ?? '').trim();
  if (!sku || vistos.has(sku)) continue;
  vistos.add(sku);
  // el resto de columnas entran como atributos, que es lo que da detalle a la ficha
  const atributos = {};
  cabecera.forEach((h, i) => {
    if (!usadas.has(i) && h && String(f[i] ?? '').trim()) atributos[h] = String(f[i]).trim();
  });
  productos.push({
    sku,
    titulo: String(f[idx.titulo] ?? '').trim(),
    marca: idx.marca !== undefined ? String(f[idx.marca] ?? '').trim() : '',
    categoria: idx.categoria !== undefined ? String(f[idx.categoria] ?? '').trim() : '',
    precio: idx.precio !== undefined ? numero(f[idx.precio]) : null,
    moneda: cfg.moneda || 'EUR',
    stock: idx.stock !== undefined ? numero(f[idx.stock]) : null,
    url: idx.url !== undefined ? String(f[idx.url] ?? '').trim() : '',
    descripcion: idx.descripcion !== undefined ? String(f[idx.descripcion] ?? '').trim() : '',
    atributos,
  });
}
if (!productos.length) throw new Error('El CSV no trajo ningún producto con referencia');
return productos.map((p) => ({ json: p }));

// Deja los productos de Shopify con la misma forma que el resto de fuentes.
const cfg = $('Configuración').first().json;
const limpiar = (html) => String(html || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const salida = [];
for (const item of $input.all()) {
  const p = item.json;
  const v = (p.variants && p.variants[0]) || {};
  const atributos = {};
  for (const op of p.options || []) {
    const vals = (op.values || []).filter(Boolean);
    if (op.name && vals.length) atributos[String(op.name).toLowerCase()] = vals.join(', ');
  }
  if (p.tags) atributos.etiquetas = String(p.tags);
  if (v.weight) atributos.peso = `${v.weight} ${v.weight_unit || 'g'}`;
  salida.push({ json: {
    sku: v.sku || String(p.id),
    id_tienda: p.id,
    titulo: p.title || '',
    marca: p.vendor || '',
    categoria: p.product_type || '',
    precio: v.price != null ? parseFloat(v.price) : null,
    moneda: cfg.moneda || 'EUR',
    stock: v.inventory_quantity ?? null,
    url: p.handle ? `https://${cfg.dominio_tienda || 'tu-tienda.myshopify.com'}/products/${p.handle}` : '',
    descripcion: limpiar(p.body_html),
    atributos,
  } });
}
if (!salida.length) throw new Error('Shopify no devolvió productos: revisa la credencial y que haya catálogo');
return salida;

// Deja los productos de WooCommerce con la misma forma que el resto de fuentes.
const cfg = $('Configuración').first().json;
const limpiar = (html) => String(html || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const salida = [];
for (const item of $input.all()) {
  const p = item.json;
  const atributos = {};
  for (const a of p.attributes || []) {
    const vals = (a.options || []).filter(Boolean);
    if (a.name && vals.length) atributos[String(a.name).toLowerCase()] = vals.join(', ');
  }
  if (p.weight) atributos.peso = `${p.weight} kg`;
  const d = p.dimensions || {};
  if (d.length && d.width) atributos.medidas = `${d.length} × ${d.width}${d.height ? ` × ${d.height}` : ''} cm`;
  salida.push({ json: {
    sku: p.sku || String(p.id),
    id_tienda: p.id,
    titulo: p.name || '',
    marca: (p.brands && p.brands[0] && p.brands[0].name) || '',
    categoria: (p.categories || []).map((c) => c.name).join(', '),
    precio: p.price != null && p.price !== '' ? parseFloat(p.price) : null,
    moneda: cfg.moneda || 'EUR',
    stock: p.stock_quantity ?? null,
    url: p.permalink || '',
    descripcion: limpiar(p.description || p.short_description),
    atributos,
  } });
}
if (!salida.length) throw new Error('WooCommerce no devolvió productos: revisa la credencial y que haya catálogo');
return salida;

// Filtra el catálogo, aplica el tope por ejecución y deja un producto por item,
// con los "hechos" que luego sirven para comprobar que la ficha no se inventa nada.
const cfg = $('Configuración').first().json;
const productos = $input.all().map((i) => i.json).filter((p) => p && p.sku && p.titulo);
if (!productos.length) throw new Error('No llegó ningún producto con referencia y título');

const corta = (p) => String(p.descripcion || '').replace(/<[^>]*>/g, '').trim().length < cfg.descripcion_corta;
const candidatos = cfg.solo_sin_descripcion ? productos.filter(corta) : productos;
const total = productos.length;
const elegidos = candidatos.slice(0, cfg.max_productos);

if (!elegidos.length) {
  return [{ json: { sin_trabajo: true, total_catalogo: total, candidatos: 0, motor: cfg.motor, ficha: null } }];
}

const textoAtributos = (p) => Object.entries(p.atributos || {})
  .map(([k, v]) => `${k.replace(/_/g, ' ')}: ${v}`).join('; ');

const TONOS = {
  es: {
    cercano: 'cercano y claro, de tú, sin exagerar',
    tecnico: 'preciso y técnico, centrado en datos y materiales',
    premium: 'sobrio y cuidado, con vocabulario de producto de gama alta, sin florituras',
  },
  en: {
    cercano: 'friendly and plain, second person, no hype',
    tecnico: 'precise and technical, focused on specs and materials',
    premium: 'restrained and refined, high-end product vocabulary, no fluff',
  },
};

return elegidos.map((p) => {
  const hechos = [
    `Referencia: ${p.sku}`,
    `Nombre: ${p.titulo}`,
    p.marca ? `Marca: ${p.marca}` : '',
    p.categoria ? `Categoría: ${p.categoria}` : '',
    p.precio != null ? `Precio: ${p.precio} ${p.moneda || 'EUR'}` : '',
    textoAtributos(p) ? `Características: ${textoAtributos(p)}` : '',
    p.descripcion ? `Texto actual: ${p.descripcion}` : '',
  ].filter(Boolean).join('\n');

  const instrucciones = cfg.idioma === 'en'
    ? `You write product copy for the online shop "${cfg.tienda}". Tone: ${TONOS.en[cfg.tono]}.`
    : `Escribes fichas de producto para la tienda online "${cfg.tienda}". Tono: ${TONOS.es[cfg.tono]}.`;
  const reglas = cfg.idioma === 'en'
    ? `Use ONLY the facts given. Never invent measurements, materials, certifications, guarantees or shipping claims. If a fact is missing, leave it out.`
    : `Usa SOLO los datos que te doy. No inventes medidas, materiales, certificados, garantías ni plazos de envío. Si un dato no está, no lo menciones.`;
  const formato = `Devuelve solo un objeto JSON con estas claves: titulo_seo (máx ${cfg.largo_titulo} caracteres), meta_descripcion (máx ${cfg.largo_meta}), bullets (array de 3 a 5 frases cortas), descripcion_html (2 párrafos <p> y una lista <ul><li>), keywords (array de 4 a 8), alt_imagen (una frase).`;

  return { json: {
    sku: p.sku,
    motor: cfg.motor,
    modelo: cfg.modelo,
    producto: p,
    hechos,
    total_catalogo: total,
    candidatos: candidatos.length,
    prompt_sistema: `${instrucciones}\n${reglas}\n${formato}`,
    prompt_usuario: hechos + (cfg.palabras_clave_extra.length ? `\nPalabras clave a incluir si encajan: ${cfg.palabras_clave_extra.join(', ')}` : ''),
  } };
});

// Motor "plantilla": escribe la ficha a partir de los datos del producto, sin llamar a ninguna API.
// Es determinista (misma entrada, misma salida) y por construcción no inventa nada.
const cfg = $('Configuración').first().json;

const PRIORIDAD = ['material', 'capacidad', 'medidas', 'dimensiones', 'diametro', 'altura', 'longitud',
  'potencia', 'bateria', 'autonomia', 'bluetooth', 'cancelacion', 'resistencia', 'impermeabilidad',
  'color', 'tallas', 'unidades', 'piezas', 'paginas', 'papel', 'peso', 'certificado', 'garantia'];

// Las claves llegan sin tildes (vienen de CSV o de la tienda); aquí se escriben bien.
const ETIQUETAS = {
  es: { material: 'Material', capacidad: 'Capacidad', medidas: 'Medidas', dimensiones: 'Dimensiones',
    diametro: 'Diámetro', altura: 'Altura', longitud: 'Longitud', potencia: 'Potencia', bateria: 'Batería',
    autonomia: 'Autonomía', bluetooth: 'Bluetooth', cancelacion: 'Cancelación de ruido', resistencia: 'Resistencia',
    impermeabilidad: 'Impermeabilidad', color: 'Color', tallas: 'Tallas', unidades: 'Unidades', piezas: 'Piezas',
    paginas: 'Páginas', papel: 'Papel', peso: 'Peso', certificado: 'Certificado', garantia: 'Garantía',
    mantiene_frio: 'Mantiene el frío', mantiene_calor: 'Mantiene el calor', portatil: 'Portátil',
    induccion: 'Inducción', mango: 'Mango', temperatura: 'Temperatura', encuadernacion: 'Encuadernación',
    rayado: 'Rayado', cierre: 'Cierre', reverso: 'Reverso', recambio: 'Recambio', acabado: 'Acabado',
    apta: 'Apta para', lavado: 'Lavado', carga: 'Carga', puertos: 'Puertos', tecnologia: 'Tecnología',
    grosor: 'Grosor', superficie: 'Superficie', duracion: 'Duración', aroma: 'Aroma', mecha: 'Mecha',
    cera: 'Cera', recipiente: 'Recipiente', ruido: 'Ruido', apagado: 'Apagado', luz: 'Luz', bolsa: 'Bolsa',
    resistencias: 'Resistencias', afilado: 'Afilado', interruptor: 'Interruptor', cabina: 'Cabina',
    antiadherente: 'Antiadherente', etiquetas: 'Etiquetas', datos: 'Datos', plegable: 'Plegable' },
  en: {},
};
const etiqueta = (k, idioma) => (ETIQUETAS[idioma] || {})[k]
  || String(k).replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());

const T = {
  es: {
    intro: {
      cercano: [
        (p) => `${p.titulo}${p.marca ? ` de ${p.marca}` : ''}, para el día a día.`,
        (p) => `${p.titulo}: lo justo, bien hecho${p.marca ? `, de ${p.marca}` : ''}.`,
        (p) => `Esto es ${p.titulo.toLowerCase()}${p.marca ? ` de ${p.marca}` : ''}, sin más vueltas.`,
      ],
      tecnico: [
        (p) => `${p.titulo}${p.marca ? ` (${p.marca})` : ''}: ficha técnica y características.`,
        (p) => `Características de ${p.titulo.toLowerCase()}${p.marca ? `, ${p.marca}` : ''}.`,
        (p) => `${p.titulo}. Estos son los datos que importan antes de decidir.`,
      ],
      premium: [
        (p) => `${p.titulo}${p.marca ? ` de ${p.marca}` : ''}. Materiales escogidos y acabado cuidado.`,
        (p) => `${p.titulo}: la versión sobria${p.marca ? `, firmada por ${p.marca}` : ''}.`,
        (p) => `${p.titulo}. Pocas piezas, bien resueltas.`,
      ],
    },
    cierre: {
      cercano: [
        () => `Una compra para años, no para una temporada.`,
        () => `Sencillo de usar y fácil de mantener.`,
        () => `De esas cosas que se compran una vez.`,
      ],
      tecnico: [
        () => `Consulta las características antes de comprar para asegurarte de que encaja con tu uso.`,
        () => `Todos los datos de arriba vienen de la ficha del fabricante.`,
        () => `Si necesitas una medida concreta, la tienes en la lista.`,
      ],
      premium: [
        () => `Una pieza pensada para quedarse, no para reemplazarse cada temporada.`,
        () => `El tipo de objeto que mejora con el uso.`,
        () => `Sin adornos: materiales, proporción y oficio.`,
      ],
    },
    cadaUno: 'Características',
    conector: 'con',
  },
  en: {
    intro: {
      cercano: [
        (p) => `${p.titulo}${p.marca ? ` by ${p.marca}` : ''}, made for everyday use.`,
        (p) => `${p.titulo}: the essentials, done properly${p.marca ? `, by ${p.marca}` : ''}.`,
        (p) => `This is ${p.titulo.toLowerCase()}${p.marca ? ` by ${p.marca}` : ''}, nothing more.`,
      ],
      tecnico: [
        (p) => `${p.titulo}${p.marca ? ` (${p.marca})` : ''}: specs and key features.`,
        (p) => `Specifications for ${p.titulo.toLowerCase()}${p.marca ? `, ${p.marca}` : ''}.`,
        (p) => `${p.titulo}. The numbers that matter before you decide.`,
      ],
      premium: [
        (p) => `${p.titulo}${p.marca ? ` by ${p.marca}` : ''}. Considered materials, careful finish.`,
        (p) => `${p.titulo}: the restrained version${p.marca ? `, signed by ${p.marca}` : ''}.`,
        (p) => `${p.titulo}. Few parts, all of them resolved.`,
      ],
    },
    cierre: {
      cercano: [
        () => `Something to keep for years, not for one season.`,
        () => `Easy to use, easy to look after.`,
        () => `One of those things you buy once.`,
      ],
      tecnico: [
        () => `Check the specs above to make sure it fits your use case.`,
        () => `Every figure above comes from the manufacturer's sheet.`,
        () => `If you need an exact measurement, it is in the list.`,
      ],
      premium: [
        () => `Built to stay, not to be replaced every season.`,
        () => `The kind of object that improves with use.`,
        () => `No decoration: materials, proportion and craft.`,
      ],
    },
    cadaUno: 'Features',
    conector: 'with',
  },
};

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mayus = (s) => String(s).charAt(0).toUpperCase() + String(s).slice(1);
// Une piezas mientras quepan: así nunca se corta un valor por la mitad
// (un "2,4 kg" recortado en "2." sería un dato falso en la ficha).
const unir = (primera, piezas, sep, max) => {
  let out = String(primera).trim();
  for (const pieza of piezas) {
    const cand = `${out}${sep}${String(pieza).trim()}`;
    if (cand.length <= max) out = cand;
  }
  return out;
};
// corta por palabra entera y sin dejar signos colgando
const recortar = (s, max) => {
  const t = String(s).replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cortado = t.slice(0, max + 1);
  const hasta = cortado.lastIndexOf(' ');
  return (hasta > max * 0.5 ? cortado.slice(0, hasta) : t.slice(0, max)).replace(/[\s,;:.·|-]+$/, '');
};

const salida = [];
for (const item of $input.all()) {
  const d = item.json;
  if (d.sin_trabajo) { salida.push({ json: d }); continue; }
  const p = d.producto;
  const L = T[cfg.idioma] || T.es;
  const attrs = Object.entries(p.atributos || {});
  attrs.sort((a, b) => {
    const ia = PRIORIDAD.indexOf(a[0]); const ib = PRIORIDAD.indexOf(b[0]);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
  });
  const bullets = attrs.slice(0, 5).map(([k, v]) => `${etiqueta(k, cfg.idioma)}: ${v}`);
  const primeraOpcion = (v) => String(v).split(/,\s+/)[0].trim();   // "S, M, L" -> "S"; "2,4 kg" intacto
  const destacado = attrs.length ? primeraOpcion(attrs[0][1]) : '';

  const sinTildes = (s) => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const yaEsta = destacado && sinTildes(destacado).split(/\s+/).filter((w) => w.length > 3)
    .some((w) => sinTildes(p.titulo).includes(w));
  const titulo_seo = unir(recortar(p.titulo, cfg.largo_titulo),
    [!yaEsta && destacado && destacado.length <= 22 ? destacado : '', p.marca].filter(Boolean),
    ' · ', cfg.largo_titulo);
  const rasgos = attrs.slice(0, 3).map(([, v]) => primeraOpcion(v)).filter(Boolean);
  const cabeza = recortar(`${p.titulo}${p.marca ? ` de ${p.marca}` : ''}`, cfg.largo_meta - 1);
  let meta = cabeza;
  rasgos.forEach((rasgo, i) => {
    const cand = `${meta}${i === 0 ? ': ' : ', '}${rasgo}`;
    if (cand.length + 1 <= cfg.largo_meta) meta = cand;
  });
  meta += '.';

  const semilla = [...String(p.sku)].reduce((a, c) => a + c.charCodeAt(0), 0);
  const intro = L.intro[cfg.tono][semilla % L.intro[cfg.tono].length](p);
  const cierre = L.cierre[cfg.tono][semilla % L.cierre[cfg.tono].length](p);
  const descripcion_html = `<p>${esc(intro)}</p>\n<ul>\n${bullets.map((b) => `  <li>${esc(b)}</li>`).join('\n')}\n</ul>\n<p>${esc(cierre)}</p>`;

  const palabras = `${p.titulo} ${p.categoria} ${p.marca}`.toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .split(/[^a-z0-9]+/).filter((w) => w.length > 3);
  const frases = [p.titulo, p.categoria, p.marca && p.categoria ? `${p.categoria} ${p.marca}` : '']
    .filter(Boolean).map((s) => String(s).toLowerCase());
  const keywords = [...new Set([...frases, ...palabras, ...cfg.palabras_clave_extra.map((k) => String(k).toLowerCase())])].slice(0, 8);
  const alt_imagen = recortar([p.titulo, p.marca, p.atributos && p.atributos.color].filter(Boolean).join(', '), 120);

  salida.push({ json: { ...d, motor: 'plantilla', ficha: {
    sku: p.sku, titulo_seo, meta_descripcion: meta, bullets, descripcion_html, keywords, alt_imagen,
  } } });
}
return salida;

// Convierte la respuesta de la API en una ficha con la misma forma que la del motor "plantilla".
// Si una respuesta viene rota, ese producto se marca y el resto sigue: nunca tumba la ejecución.
const cfg = $('Configuración').first().json;
const preparados = $('Preparar productos').all().map((i) => i.json);
const entradas = $input.all();

const texto = (r) => {
  if (typeof r === 'string') return r;
  if (r?.choices?.[0]?.message?.content) return r.choices[0].message.content;
  if (r?.message?.content) return r.message.content;
  if (r?.content) return typeof r.content === 'string' ? r.content : (r.content[0]?.text || '');
  return '';
};
const extraerJson = (s) => {
  const limpio = String(s).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(limpio); } catch (_) { /* sigue */ }
  const ini = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');
  if (ini >= 0 && fin > ini) {
    try { return JSON.parse(limpio.slice(ini, fin + 1)); } catch (_) { /* sigue */ }
  }
  return null;
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const salida = [];
entradas.forEach((item, i) => {
  const base = preparados[i] || preparados[0] || {};
  if (base.sin_trabajo) { salida.push({ json: base }); return; }
  const p = base.producto || {};
  // Si la API respondió con un error (clave no válida, sin saldo, límite de uso…), se dice tal cual.
  const errorApi = item.json && (item.json.error || item.json.errorMessage);
  if (errorApi) {
    const msg = typeof errorApi === 'object' ? (errorApi.description || errorApi.message || JSON.stringify(errorApi)) : String(errorApi);
    salida.push({ json: { ...base, motor: cfg.motor, ficha: null,
      fallo: `La API de IA devolvió un error para ${p.sku || base.sku}: ${msg.slice(0, 160)}` } });
    return;
  }
  const crudo = texto(item.json);
  const j = extraerJson(crudo);
  if (!j || !j.titulo_seo) {
    salida.push({ json: { ...base, motor: cfg.motor, ficha: null,
      fallo: `La respuesta de la API no traía un JSON válido para ${p.sku || base.sku}` } });
    return;
  }
  const lista = (v) => (Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean) : String(v || '')
    .split(/\n|;|•/).map((x) => x.replace(/^[-*\s]+/, '').trim()).filter(Boolean));
  const bullets = lista(j.bullets).slice(0, 5);
  const html = String(j.descripcion_html || '').trim()
    || `<p>${esc(j.resumen || j.meta_descripcion || '')}</p>\n<ul>\n${bullets.map((b) => `  <li>${esc(b)}</li>`).join('\n')}\n</ul>`;
  salida.push({ json: { ...base, motor: cfg.motor, ficha: {
    sku: p.sku || base.sku,
    titulo_seo: String(j.titulo_seo).trim(),
    meta_descripcion: String(j.meta_descripcion || j.meta || '').trim(),
    bullets,
    descripcion_html: html,
    keywords: lista(j.keywords).slice(0, 8),
    alt_imagen: String(j.alt_imagen || j.alt || '').trim(),
  } } });
});
return salida;

// Revisa las fichas, monta el CSV para importar en la tienda y el email de resumen.
const cfg = $('Configuración').first().json;
const items = $input.all().map((i) => i.json).filter(Boolean);

const vacio = items.length === 1 && items[0].sin_trabajo;
const TAGS_OK = /^(p|ul|ol|li|br|strong|em|h2|h3)$/i;

const numeros = (s) => (String(s).match(/\d+(?:[.,]\d+)?/g) || []).map((n) => n.replace(',', '.'));

const revisadas = [];
const fallos = [];
for (const it of items) {
  if (it.sin_trabajo) continue;
  if (!it.ficha) { fallos.push(it.fallo || `Sin ficha para ${it.sku}`); continue; }
  const f = it.ficha;
  const avisos = [];

  if (f.titulo_seo.length > cfg.largo_titulo) avisos.push(`título de ${f.titulo_seo.length} caracteres (máx ${cfg.largo_titulo})`);
  if (!f.meta_descripcion) avisos.push('sin meta descripción');
  else if (f.meta_descripcion.length > cfg.largo_meta) avisos.push(`meta de ${f.meta_descripcion.length} caracteres (máx ${cfg.largo_meta})`);
  if (f.bullets.length < 3) avisos.push(`solo ${f.bullets.length} características`);
  if (!f.alt_imagen) avisos.push('sin texto alternativo de imagen');
  if (f.keywords.length < 3) avisos.push('menos de 3 palabras clave');

  const etiquetasRaras = [...new Set((f.descripcion_html.match(/<\/?([a-z0-9]+)/gi) || [])
    .map((t) => t.replace(/[<\/]/g, '')).filter((t) => !TAGS_OK.test(t)))];
  if (etiquetasRaras.length) avisos.push(`etiquetas HTML no permitidas: ${etiquetasRaras.join(', ')}`);

  // Ningún número puede aparecer en la ficha si no estaba en los datos del producto:
  // es la comprobación que impide que el texto se invente medidas, garantías o plazos.
  const enDatos = new Set(numeros(it.hechos));
  const generado = [f.titulo_seo, f.meta_descripcion, ...f.bullets, f.descripcion_html.replace(/<[^>]*>/g, ' '), f.alt_imagen].join(' ');
  const inventados = [...new Set(numeros(generado))].filter((n) => !enDatos.has(n));
  if (inventados.length) avisos.push(`datos sin respaldo en el producto: ${inventados.join(', ')}`);

  if (/lorem|ipsum|\bTODO\b|XXX|\[[^\]]*\]/i.test(generado)) avisos.push('texto de relleno sin sustituir');

  revisadas.push({ ...f, url: it.producto?.url || '', avisos, revisar: avisos.length > 0 });
}

const total = items[0]?.total_catalogo ?? revisadas.length;
const candidatos = items[0]?.candidatos ?? revisadas.length;
const conAviso = revisadas.filter((f) => f.revisar);

// ---- CSV para importar en la tienda ----
const COLS = ['sku', 'titulo_seo', 'meta_descripcion', 'descripcion_html', 'bullets', 'keywords', 'alt_imagen', 'avisos'];
const celda = (v) => {
  // sin saltos de línea dentro de las celdas: hay importadores de tienda que los parten mal
  const s = (Array.isArray(v) ? v.join(' | ') : String(v ?? '')).replace(/\r?\n\s*/g, ' ').trim();
  return /[";]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = [COLS.join(';'), ...revisadas.map((f) => COLS.map((c) => celda(f[c])).join(';'))].join('\n');

// ---- Email ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const VERDE = '#235b54'; const TINTA = '#35322c'; const SUAVE = '#6e6a61';
const REGLA = '#e7e4dc'; const PAPEL = '#f4f3ef'; const ALERTA = '#8f2f24';
const h3 = (t) => `<h3 style="font-family:Georgia,'Times New Roman',serif;font-size:17px;color:${VERDE};margin:24px 0 8px;font-weight:normal">${t}</h3>`;
const th = (t, der) => `<th align="${der ? 'right' : 'left'}" style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${SUAVE};border-bottom:1px solid ${REGLA};padding:6px 0;font-weight:normal">${t}</th>`;
const td = (t, der) => `<td align="${der ? 'right' : 'left'}" style="font-size:13px;color:${TINTA};border-bottom:1px solid ${REGLA};padding:8px 0">${t}</td>`;

const filas = revisadas.slice(0, 12).map((f) => `<tr>${td(esc(f.sku))}${td(esc(f.titulo_seo))}${td(
  f.revisar ? `<span style="color:${ALERTA}">revisar</span>` : 'lista', 1)}</tr>`).join('');
const muestra = revisadas[0];
const cifra = (n, t) => `<td width="33%" style="padding:0 8px"><div style="font-family:Georgia,serif;font-size:30px;color:${VERDE};line-height:1">${n}</div><div style="font-size:12px;color:${SUAVE};padding-top:2px">${t}</div></td>`;

const cuerpo = vacio
  ? `<p style="font-size:15px;color:${TINTA};margin:0">No había ningún producto pendiente de ficha: los ${total} del catálogo ya tienen descripción.</p>`
  : `<table width="100%" cellspacing="0" style="margin:4px 0 8px"><tr>
${cifra(revisadas.length, 'fichas escritas')}${cifra(conAviso.length, 'para revisar')}${cifra(`${candidatos}/${total}`, 'pendientes del catálogo')}
</tr></table>
${h3('Fichas generadas')}
<table width="100%" cellspacing="0" style="border-collapse:collapse"><tr>${th('Ref.')}${th('Título SEO')}${th('Estado', 1)}</tr>${filas}</table>
${revisadas.length > 12 ? `<p style="font-size:12px;color:${SUAVE};margin:8px 0 0">…y ${revisadas.length - 12} más en el CSV adjunto.</p>` : ''}
${muestra ? `${h3('Así queda una ficha')}
<div style="border:1px solid ${REGLA};border-radius:10px;padding:16px;background:#fff">
<div style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${SUAVE}">${esc(muestra.sku)}</div>
<div style="font-family:Georgia,serif;font-size:18px;color:${TINTA};margin:4px 0 6px">${esc(muestra.titulo_seo)}</div>
<div style="font-size:13px;color:${SUAVE};margin-bottom:10px">${esc(muestra.meta_descripcion)}</div>
<div style="font-size:13px;color:${TINTA}">${muestra.descripcion_html}</div>
</div>` : ''}
${conAviso.length ? `${h3('⚠️ Repasa antes de publicar')}
<ul style="font-size:13px;color:${TINTA};padding-left:18px;margin:0">${conAviso.slice(0, 8).map((f) => `<li style="margin-bottom:4px"><b>${esc(f.sku)}</b>: ${esc(f.avisos.join('; '))}</li>`).join('')}</ul>` : ''}
${fallos.length ? `<p style="font-size:13px;color:${ALERTA};margin-top:16px">${fallos.length} producto(s) sin ficha: ${esc(fallos.slice(0, 3).join(' · '))}</p>` : ''}
<p style="font-size:13px;color:${SUAVE};margin-top:20px">El CSV adjunto se importa tal cual en la tienda. Las fichas marcadas como «revisar» llevan el motivo en la última columna.</p>`;

const email_html = `<!doctype html><html><body style="margin:0;background:${PAPEL};font-family:Arial,Helvetica,sans-serif;color:${TINTA}">
<table width="100%" cellspacing="0"><tr><td align="center" style="padding:24px">
<table width="680" cellspacing="0" style="background:#fff;border-radius:12px"><tr><td style="padding:28px">
<div style="font-family:Georgia,'Times New Roman',serif;font-size:22px;color:${VERDE}">Fichas de producto · ${esc(cfg.tienda)}</div>
<div style="font-size:12px;color:${SUAVE};padding:2px 0 12px;border-bottom:1px solid ${REGLA}">${new Date(cfg.generado_en).toLocaleString('es-ES', { dateStyle: 'long', timeStyle: 'short' })} · motor: ${esc(items.find((i) => i.motor)?.motor || cfg.motor)}</div>
${cuerpo}
<div style="border-top:1px solid ${REGLA};margin-top:24px;padding-top:12px;font-size:11px;color:${SUAVE}">Denoro Automations</div>
</td></tr></table></td></tr></table></body></html>`;

const telegram = vacio
  ? `✅ <b>Fichas de producto</b>\nNada pendiente: los ${total} productos ya tienen descripción.`
  : `✅ <b>Fichas de producto · ${cfg.tienda}</b>\n` +
    `<b>Escritas:</b> ${revisadas.length}\n<b>Para revisar:</b> ${conAviso.length}\n` +
    `<b>Pendientes del catálogo:</b> ${candidatos} de ${total}` +
    (fallos.length ? `\n⚠️ ${fallos.length} sin ficha` : '');

const nombre = `fichas-${new Date(cfg.generado_en).toISOString().slice(0, 10)}.csv`;
return [{
  json: {
    ...cfg,
    asunto: vacio
      ? `Denoro · ${cfg.tienda}: nada pendiente de ficha`
      : `Denoro · ${revisadas.length} fichas para ${cfg.tienda}${conAviso.length ? ` (${conAviso.length} a revisar)` : ''}`,
    email_html, telegram,
    resumen: { escritas: revisadas.length, con_aviso: conAviso.length, sin_ficha: fallos.length, catalogo: total, candidatos },
    fichas: revisadas,
  },
  binary: vacio ? {} : { fichas: {
    data: Buffer.from('﻿' + csv, 'utf8').toString('base64'),
    mimeType: 'text/csv', fileName: nombre, fileExtension: 'csv',
  } },
}];

// (Se añade a cada automatización en su versión «para un cliente»)
// Guarda en denoro_estado lo que ha pasado en esta ejecución, para enseñarlo en el panel.
const d = $input.first()?.json || {};
const cfg = $('Configuración').first().json;
const txt = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const titulo = txt(d.asunto).replace(/^[^\p{L}\p{N}]*Denoro · /u, '').replace(/^[^\p{L}\p{N}]+/u, '');
return [{ json: {
  clave: cfg.__clave, token: cfg.__token, snapshot: '',
  resumen: JSON.stringify({
    ultima: new Date().toISOString(), ok: true, modo: cfg.modo || null,
    titulo: (titulo || "Sin productos pendientes").slice(0, 200),
    texto: txt(d.telegram).slice(0, 1500),
    avisado: Boolean(d.asunto && (d.enviar_email || d.enviar_telegram)),
    demo: [cfg.fuente, cfg.destino].includes('demo'),
  }),
} }];
